cd multicode/duckpit/build/onepit/iter8d/rw-P && python3 -I - <<'EOF'
import re
for f in ['x4/X1_s5501.log','x4/X1_s5502.log']:
    rows=[]
    for ln in open(f,errors='replace'):
        m=re.search(r'\[onepit\] goals n=(\d+) open=(\d+) list=(\S*) t=([0-9.]+)',ln)
        if m: rows.append((float(m.group(4)),int(m.group(1)),int(m.group(2))))
    print(f,len(rows))
    for lo in range(0,2800,300):
        w=[r for r in rows if lo<=r[0]<lo+300]
        if w: print(' %2d-%2d min: n min/max %d/%d open min/max %d/%d'%(lo//60,(lo+300)//60,min(x[1] for x in w),max(x[1] for x in w),min(x[2] for x in w),max(x[2] for x in w)))
EOF

